/* =========================================================
   BUSCADOR DE RESIDENCIAL EN LA PANTALLA DE INICIO
   ========================================================= */
const normTxt=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
function filtraRes(q){const box=document.getElementById('resList');if(!box)return;const n=normTxt(q);
  const res=PLAT.residenciales.map(r=>{const nm=normTxt(r.nombre);const pal=nm.split(/\s+/);const rank=!n?2:nm.startsWith(n)?0:pal.some(w=>w.startsWith(n))?1:-1;return{r,rank}}).filter(x=>x.rank>=0).sort((a,b)=>a.rank-b.rank||a.r.nombre.localeCompare(b.r.nombre)).slice(0,8);
  const appOk=!n||normTxt('Administrador de la APP').split(' ').some(w=>w.startsWith(n))||normTxt('Administrador de la APP').startsWith(n);
  box.innerHTML=res.map(x=>`<button type="button" class="combo-it" onmousedown="event.preventDefault();elegirRes('${x.r.id}')">${ic('houses',16)} <span>${esc(x.r.nombre)}</span><small>${esc(x.r.municipio||'')}</small></button>`).join('')+(appOk?`<button type="button" class="combo-it" onmousedown="event.preventDefault();elegirRes('plat')">⚙️ <span>Administrador de la APP</span></button>`:'')+(!res.length&&!appOk?'<div class="empty" style="padding:12px">Sin coincidencias</div>':'');
  box.hidden=false}
function elegirRes(id){const box=document.getElementById('resList');if(box)box.hidden=true;cambiarRes(id);setTimeout(()=>{const u=document.querySelector('.login [name=user]');if(u)u.focus()},30)}
function teclaRes(e){if(e.key==='Enter'){e.preventDefault();const b=document.querySelector('#resList .combo-it');if(b)b.dispatchEvent(new MouseEvent('mousedown'))}else if(e.key==='Escape'){document.getElementById('resList').hidden=true}}

/* =========================================================
   DIRECTORIO: EMERGENCIAS Y SERVICIOS DE CONFIANZA
   ========================================================= */
const CAT_EM=['Emergencias (911)','Policía','Protección Civil','Bomberos','Ambulancia / Cruz Roja','Administración','Caseta / Portería','Vigilante','Cobrador','Otro'];
const OFICIOS_S=['Plomero','Electricista','Albañil','Empleada de casa','Niñera','Jardinero','Pintor','Carpintero','Cerrajero','Técnico de electrodomésticos','Técnico de internet / cable','Mecánico','Servicios varios','Otro'];
function dirDB(){if(!DB.directorio)DB.directorio={emergencia:[],servicios:[]};return DB.directorio}
function seedDirectorio(d,ejemplo){const r=d.residencial;const em=[{id:uid(),categoria:'Emergencias (911)',nombre:'Emergencias',telefono:'911',nota:''}];
  if(r.vigilancia&&r.vigilancia.telefono)em.push({id:uid(),categoria:'Caseta / Portería',nombre:'Portería principal',telefono:r.vigilancia.telefono,nota:'24 horas'});
  const ad=(r.equipo||[]).find(m=>m.cargo==='Administrador(a)');if(ad&&ad.telefono)em.push({id:uid(),categoria:'Administración',nombre:ad.nombre,telefono:ad.telefono,nota:''});
  const sv=ejemplo?[{id:uid(),nombre:'Ramón Castillo',oficio:'Plomero',telefono:'7123-1111',dui:'04567123-4',zona:'Lun–Sáb 7:00–17:00',nota:'Ha trabajado en la residencial desde 2022.',verificado:true,solvencia:true,fecha:ymd(),foto:null},{id:uid(),nombre:'Carmen Alas',oficio:'Empleada de casa',telefono:'7222-3333',dui:'05678234-5',zona:'Por día o permanente',nota:'Referencias de 3 familias de la residencial.',verificado:true,solvencia:true,fecha:ymd(),foto:null},{id:uid(),nombre:'Electro Servicios Ayala',oficio:'Electricista',telefono:'7333-4444',dui:'',zona:'Emergencias 24 h',nota:'',verificado:false,solvencia:false,fecha:ymd(),foto:null}]:[];
  d.directorio={emergencia:em,servicios:sv}}
function telRow(t){const n=String(t||'').replace(/[^\d+]/g,'');return `<a class="btn smb sec" href="tel:${esc(n)}">${ic('phone',14)} ${esc(t)}</a>`}
function vDirectorio(){const adm=S.user.rol==='admin';const D=dirDB();S.dseg=S.dseg||'emergencia';
  let h=`<h2>Directorio</h2>${seg('dseg',[['emergencia','🚨 Emergencias'],['servicios','🛠️ Servicios de confianza']])}`;
  if(S.dseg==='emergencia'){h+=`<p class="note" style="margin-top:-4px">Números importantes de la residencial y de emergencia.${adm?' Agrega o corrige los que necesites.':''}</p>`+(D.emergencia.slice().sort((a,b)=>CAT_EM.indexOf(a.categoria)-CAT_EM.indexOf(b.categoria)).map(e=>`<div class="item"><div class="av">${/911|Polic|Bomb|Ambul|Civil/.test(e.categoria)?'🚨':'📞'}</div><div class="grow"><b>${esc(e.nombre)}</b><div class="sm muted">${esc(e.categoria)}${e.nota?' · '+esc(e.nota):''}</div><div style="margin-top:6px">${telRow(e.telefono)}</div></div>${adm?`<button class="btn smb ghost" onclick="editarEm('${e.id}')">Editar</button>`:''}</div>`).join('')||empty('Sin números registrados'))+(adm?`<button class="btn block" onclick="editarEm()">${ic('plus',18)} Agregar número</button>`:'')}
  else{S.dof=S.dof||'';const ofs=[...new Set(D.servicios.map(s=>s.oficio))];const l=D.servicios.filter(s=>(adm||s.activo!==false)&&(!S.dof||s.oficio===S.dof)).sort((a,b)=>(S.dord==='rating'?scoreR('serv',b.id)-scoreR('serv',a.id):0)||(b.verificado?1:0)-(a.verificado?1:0)||a.nombre.localeCompare(b.nombre));
    h+=`<p class="note" style="margin-top:-4px">Personas y empresas revisadas por la administración.${adm?' Tú decides quién aparece aquí.':' Contáctalas directamente.'}</p>${ofs.length>1?`<div class="months" style="margin-bottom:10px"><button class="chip ${!S.dof?'info':''}" style="border:0" onclick="S.dof='';render()">Todos</button>${ofs.map(o=>`<button class="chip ${S.dof===o?'info':''}" style="border:0" onclick="S.dof='${esc(o)}';render()">${esc(o)}</button>`).join('')}</div>`:''}`+(l.length>1?ordenBar('dord'):'')+(l.map(s=>servCard(s,adm)).join('')||empty('Aún no hay servicios registrados'))+(adm?`<button class="btn block" onclick="editarServ()">${ic('plus',18)} Agregar persona o empresa</button>`:'')}
  return h}
function servCard(s,adm){const ini=s.nombre.split(' ').map(w=>w[0]).slice(0,2).join('');const tel=String(s.telefono||'').replace(/\D/g,'');
  return `<div class="card"><div class="row">${s.foto&&s.foto.data?`<img src="${s.foto.data}" alt="" style="width:52px;height:52px;border-radius:50%;object-fit:cover;flex:none">`:`<div class="av" style="width:52px;height:52px;border-radius:50%">${esc(ini)}</div>`}<div class="grow"><b>${esc(s.nombre)}</b><div class="sm muted">${esc(s.oficio)}${s.zona?' · '+esc(s.zona):''}</div><div class="months">${s.verificado?chip('✓ Verificado por la administración','ok'):chip('Sin verificar','warn')}${solvChip(s)}${adm&&s.activo===false?chip('Oculto','mut'):''}</div><div style="margin-top:6px">${rateLine('serv',s.id,true)}</div></div></div>${s.nota?`<p class="sm" style="margin:8px 0 0">${esc(s.nota)}</p>`:''}
  <div class="btns">${telRow(s.telefono)}<button class="btn smb ghost" onclick="verResenas('serv','${s.id}')">${ic('star',14)} ${['residente','inquilino'].includes(S.user.rol)?'Opiniones y calificar':'Opiniones'}</button>${tel?`<a class="btn smb ghost" target="_blank" rel="noopener" href="https://wa.me/${tel.length<=8?telCode()+tel:tel}">WhatsApp</a>`:''}${['residente','inquilino'].includes(S.user.rol)?`<button class="btn smb ghost" onclick="paseDesdeServ('${s.id}')">Crear pase</button>`:''}${adm&&s.solvDoc?`<button class="btn smb ghost" onclick="verSolv('${s.id}')">Solvencia</button>`:''}${adm?`<button class="btn smb ghost" onclick="editarServ('${s.id}')">Editar</button>`:''}</div></div>`}
function editarEm(id){const e=id?dirDB().emergencia.find(x=>x.id===id):{};sheet(id?'Editar número':'Nuevo número',`<form onsubmit="guardarEm(event,'${id||''}')"><label class="f">Tipo<select name="categoria">${CAT_EM.map(c=>`<option ${e.categoria===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="f">Nombre<input name="nombre" required value="${esc(e.nombre||'')}" placeholder="Ej. Delegación PNC Santa Tecla"></label><label class="f">Teléfono<input name="telefono" required inputmode="tel" value="${esc(e.telefono||'')}"></label><label class="f">Nota (opcional)<input name="nota" value="${esc(e.nota||'')}" placeholder="Ej. 24 horas"></label><button class="btn block">Guardar</button>${id?`<button type="button" class="btn bad block" onclick="borrarDir('emergencia','${id}')">Eliminar</button>`:''}</form>`)}
function guardarEm(e,id){e.preventDefault();const f=new FormData(e.target);const o={categoria:f.get('categoria'),nombre:String(f.get('nombre')).trim(),telefono:String(f.get('telefono')).trim(),nota:String(f.get('nota')||'').trim()};const L=dirDB().emergencia;if(id)Object.assign(L.find(x=>x.id===id),o);else L.push(Object.assign({id:uid()},o));save();closeSheet();render();toast('Número guardado')}
function editarServ(id){const s=id?dirDB().servicios.find(x=>x.id===id):{verificado:true,activo:true};SERVFOTO=undefined;SERVSOLV=undefined;
  sheet(id?'Editar perfil':'Nuevo perfil de servicio',`<p class="note" style="margin-top:0">Este perfil no da acceso a la administración; solo aparece en el directorio para los residentes.</p><form onsubmit="guardarServ(event,'${id||''}')"><label class="f">Nombre o empresa<input name="nombre" required value="${esc(s.nombre||'')}"></label><label class="f">Oficio<select name="oficio">${OFICIOS_S.map(o=>`<option ${s.oficio===o?'selected':''}>${o}</option>`).join('')}</select></label><div class="two"><label class="f">Teléfono<input name="telefono" required inputmode="tel" value="${esc(s.telefono||'')}"></label><label class="f">DUI<input name="dui" inputmode="numeric" maxlength="10" autocomplete="off" value="${esc(s.dui||'')}"></label></div><label class="f">Horario / zona<input name="zona" value="${esc(s.zona||'')}" placeholder="Ej. Lun–Sáb 7:00–17:00"></label><label class="f">Referencias o nota<textarea name="nota" placeholder="Ej. Recomendado por la casa 12">${esc(s.nota||'')}</textarea></label><label class="f">Foto (opcional)<input type="file" accept="image/*" onchange="fotoServ(this)"></label>
  <label class="chk"><input type="checkbox" name="verificado" ${s.verificado?'checked':''}><span class="grow sm">Verificado por la administración (documentos y referencias revisados)</span></label><label class="chk"><input type="checkbox" name="solvencia" ${s.solvencia?'checked':''}><span class="grow sm">Presentó solvencia de la PNC</span></label><label class="f" style="margin-top:10px">Solvencia policial (foto o PDF)<input type="file" accept="image/*,application/pdf" onchange="solvServ(this)"></label>${s.solvDoc?`<button type="button" class="btn ghost smb" style="margin:-4px 0 10px" onclick="verSolv('${s.id}')">${ic('doc',14)} Ver solvencia guardada</button>`:''}<label class="f">Solvencia vigente hasta (opcional)<input type="date" name="solvVence" value="${esc(s.solvVence||'')}"></label><label class="chk"><input type="checkbox" name="activo" ${s.activo!==false?'checked':''}><span class="grow sm">Visible para los residentes</span></label>
  <button class="btn block">Guardar perfil</button>${id?`<button type="button" class="btn bad block" onclick="borrarDir('servicios','${id}')">Eliminar perfil</button>`:''}</form>`)}
let SERVFOTO;async function fotoServ(inp){try{SERVFOTO=await leerArchivo(inp.files[0])}catch(e){toast('Foto no válida')}}
function guardarServ(e,id){e.preventDefault();const f=new FormData(e.target);const g=k=>String(f.get(k)||'').trim();if(!duiOk(g('dui')))return toast('DUI incompleto. Formato: 00000000-0');
  const o={nombre:g('nombre'),oficio:g('oficio'),telefono:g('telefono'),dui:g('dui'),zona:g('zona'),nota:g('nota'),verificado:!!f.get('verificado'),solvencia:!!f.get('solvencia'),activo:!!f.get('activo'),fecha:ymd()};if(SERVFOTO)o.foto=SERVFOTO;if(SERVSOLV){o.solvDoc=SERVSOLV;o.solvencia=true}o.solvVence=g('solvVence');
  const L=dirDB().servicios;if(id)Object.assign(L.find(x=>x.id===id),o);else{L.push(Object.assign({id:uid(),foto:null},o));if(o.activo)notificar(DB.usuarios.filter(u=>u.activo&&['residente','inquilino'].includes(u.rol)).map(u=>u.id),'🛠️ Nuevo servicio de confianza',`${o.nombre} · ${o.oficio}`,{tab:'directorio'})}
  SERVFOTO=undefined;SERVSOLV=undefined;save();closeSheet();render();toast('Perfil guardado')}
function borrarDir(k,id){dirDB()[k]=dirDB()[k].filter(x=>x.id!==id);save();closeSheet();render();toast('Eliminado')}
function paseDesdeServ(id){const s=dirDB().servicios.find(x=>x.id===id);nuevoPase('personal');setTimeout(()=>{const o=document.querySelector('#ov');if(!o)return;const set=(n,v)=>{const i=o.querySelector('[name='+n+']');if(i&&v)i.value=v};set('nombre',s.nombre);set('dui',s.dui);const sel=o.querySelector('[name=detalle]');if(sel){const m=[...sel.options].find(x=>normTxt(x.value).startsWith(normTxt(s.oficio).slice(0,5)));if(m)sel.value=m.value}},30)}

/* =========================================================
   TIPO: RESIDENCIAL (SV) / CONDOMINIO-HOA (EE. UU.)
   ========================================================= */
const esCondo=()=>!!(DB&&DB.residencial&&DB.residencial.tipo==='condominio');
const TIPO_RES={residencial:'Residencial',condominio:'Condominio / HOA'};

/* =========================================================
   IDIOMA (ESPAÑOL / ENGLISH) Y TÉRMINOS DE CONDOMINIO
   ========================================================= */
let LANG='es';try{LANG=localStorage.getItem(KEY+'_lang')||'es'}catch(e){}
function setLang(l){LANG=l;try{localStorage.setItem(KEY+'_lang',l)}catch(e){}closeSheet();render()}
const langBtn=()=>`<button class="btn ghost smb" onclick="setLang('${LANG==='en'?'es':'en'}')">${LANG==='en'?'🇸🇻 Español':'🇺🇸 English'}</button>`;
const TERM_ES=[[/\bCasas\b/g,'Unidades'],[/\bcasas\b/g,'unidades'],[/\bCasa\b/g,'Unidad'],[/\bcasa\b/g,'unidad'],[/\bPolígonos\b/g,'Edificios'],[/\bpolígonos\b/g,'edificios'],[/\bPolígono\b/g,'Edificio'],[/\bpolígono\b/g,'edificio'],[/\bPol\. /g,'Edif. '],[/\bDUI\b/g,'ID'],[/\bla colonia\b/g,'el condominio'],[/\bcolonia\b/g,'condominio'],[/\bresidencial\b/g,'condominio'],[/\bResidencial\b(?! [A-ZÁÉÍÓÚ])/g,'Condominio']];
const TERM_EN=[[/\bHouses\b/g,'Units'],[/\bhouses\b/g,'units'],[/\bHouse\b/g,'Unit'],[/\bhouse\b/g,'unit'],[/\bBlocks\b/g,'Buildings'],[/\bblocks\b/g,'buildings'],[/\bBlock\b/g,'Building'],[/\bblock\b/g,'building'],[/\bDUI\b/g,'ID'],[/\bneighborhood\b/g,'community'],[/\bmaintenance fee\b/g,'HOA dues'],[/\bMaintenance fee\b/g,'HOA dues']];
function trS(s){if(LANG!=='en'&&!esCondo()&&paisRes()==='SV')return s;const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/);let t=m[2];if(!t)return s;
  if(LANG==='en')t=trEN(t);
  if(esCondo())for(const[re,rep]of(LANG==='en'?TERM_EN:TERM_ES))t=t.replace(re,rep);
  if(paisRes()!=='SV')t=t.replace(/\bDUI\b/g,LANG==='en'&&paisCfg().id==='DUI'?'ID':paisCfg().id).replace(/00000000-0/g,'');
  return m[1]+t+m[3]}
function trNodo(root){if(LANG!=='en'&&!esCondo()&&paisRes()==='SV')return;if(!root)return;if(root.nodeType===3){const v=trS(root.nodeValue);if(v!==root.nodeValue)root.nodeValue=v;return}if(root.nodeType!==1)return;
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentNode&&/^(SCRIPT|STYLE|TEXTAREA)$/.test(n.parentNode.nodeName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const ns=[];while(w.nextNode())ns.push(w.currentNode);ns.forEach(n=>{const v=trS(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v});
  (root.querySelectorAll?[root,...root.querySelectorAll('[placeholder],[aria-label],[title]')]:[]).forEach(el=>{['placeholder','aria-label','title'].forEach(a=>{const v=el.getAttribute&&el.getAttribute(a);if(v){const t=trS(v);if(t!==v)el.setAttribute(a,t)}})})}
new MutationObserver(ms=>{if(LANG!=='en'&&!esCondo()&&paisRes()==='SV')return;ms.forEach(m=>m.addedNodes.forEach(trNodo))}).observe(document.body,{childList:true,subtree:true});

