function trEN(t){if(t.includes(' · ')){const ps=t.split(' · ');const tp=ps.map(trSeg);if(tp.some((x,i)=>x!==ps[i]))return tp.join(' · ')}let r=trSeg(t);if(r!==t)return r;const d=t.match(/^(.+?)([.:!?])$/);if(d){const x=trSeg(d[1]);if(x!==d[1])return x+d[2]}return t}

