function camposDir(pc,dv){const c=PAISES[pc]||PAISES.SV;dv=dv||{};const inp=(n,l,v,x='')=>`<label class="f">${l}<input name="${n}" value="${esc(v||'')}" ${x}></label>`;
  const reg=c.reg?(c.reg.ops?`<label class="f">${c.reg.l}<select name="region" required><option value="">Selecciona…</option>${c.reg.ops.map(o=>{const v=c.us?o.slice(0,2):o;return `<option value="${esc(v)}" ${dv.region===v?'selected':''}>${esc(c.us?o.slice(3)+' ('+o.slice(0,2)+')':o)}</option>`}).join('')}</select></label>`:inp('region',c.reg.l,dv.region,'required')):'';
  return `${inp('linea',c.line,dv.linea,'required')}${c.line2?inp('linea2',c.line2,dv.linea2):''}${c.us?`${inp('ciudad',c.city,dv.ciudad,'required')}<div class="two">${reg||'<span></span>'}${c.zip?inp('zip',c.zip.l,dv.zip,`${c.zip.opt?'':'required'} placeholder="${c.zip.ph||''}" autocapitalize="characters"`):''}</div>`:`${reg}${inp('ciudad',c.city,dv.ciudad,'required')}${c.zip?inp('zip',c.zip.l,dv.zip,`${c.zip.opt?'':'required'} placeholder="${c.zip.ph||''}" inputmode="numeric"`):''}`}<p class="note" style="margin-top:-4px">Moneda: ${c.mon} · Documento de identidad: ${c.id} · Teléfono: +${c.tel}</p>`}
function selPais(sel){return `<label class="f">País<select name="pais" onchange="document.getElementById('dirCampos').innerHTML=camposDir(this.value)">${Object.entries(PAISES).map(([k,p])=>`<option value="${k}" ${k===sel?'selected':''}>${p.f} ${p.n}</option>`).join('')}</select></label><div id="dirCampos">`}
function leerDir(f){const g=k=>String(f.get(k)||'').trim();const pc=g('pais')||'SV';const c=PAISES[pc]||PAISES.SV;const dv={region:g('region'),ciudad:g('ciudad'),linea:g('linea'),linea2:g('linea2'),zip:g('zip').toUpperCase()};
  if(c.zip&&dv.zip&&!c.zip.re.test(dv.zip))return{err:c.zip.l+' no válido'+(c.zip.ph?' (ej. '+c.zip.ph+')':'')};if(c.zip&&!c.zip.opt&&!dv.zip)return{err:'Falta '+c.zip.l};
  const direccion=[dv.linea,dv.linea2].filter(Boolean).join(', ');const municipio=c.us?[dv.ciudad,[dv.region,dv.zip].filter(Boolean).join(' ')].filter(Boolean).join(', '):[dv.ciudad,dv.region].filter(Boolean).join(', ')+(dv.zip?' · CP '+dv.zip:'');
  return{pais:pc,dir:dv,direccion,municipio}}

